"""Mirror the exact server sources into an Editor-only compilation location.
Run after changing server code. Do not copy ServerSources into runtime Assets.
--check only verifies existing generated bytes (no mutation).
"""
from pathlib import Path
import sys,hashlib,json
root=Path(__file__).resolve().parents[1]
source=root/'ServerSources'
destination=root/'Assets/Editor/LocalMockGenerated'
files=[*sorted(source.glob('*.cs')),source/'Testing/InMemoryWorldStore.cs',source/'Testing/PetTradeMockScenario.cs']
manifest={}
for p in files:
    relative=p.relative_to(source)
    data='// GENERATED from ServerSources/'+relative.as_posix()+'. Do not edit.\n#if UNITY_EDITOR\n'+p.read_text()+'\n#endif\n'
    target=destination/relative
    if '--check' in sys.argv:
        assert target.exists() and target.read_text()==data, 'Stale editor mock: '+str(target)
    else:
        target.parent.mkdir(parents=True,exist_ok=True);target.write_text(data)
    manifest[relative.as_posix()]=hashlib.sha256(p.read_bytes()).hexdigest()
if '--check' not in sys.argv:
    (destination/'SOURCES.json').write_text(json.dumps(manifest,indent=2)+'\n')
print('PASS: editor-only server mock copies match',len(files),'source files.')
